    "css": ".radio-inputs {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  max-width: 350px;\n  -webkit-user-select: none;\n  -moz-user-select: none;\n  -ms-user-select: none;\n  user-select: none;\n}\n\n.radio-inputs > * {\n  margin: 6px;\n}\n\n.radio-input:checked + .radio-tile {\n  border-color: #2260ff;\n  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);\n  color: #2260ff;\n}\n\n.radio-input:checked + .radio-tile:before {\n  transform: scale(1);\n  opacity: 1;\n  background-color: #2260ff;\n  border-color: #2260ff;\n}\n\n.radio-input:checked + .radio-tile .radio-icon svg {\n  fill: #2260ff;\n}\n\n.radio-input:checked + .radio-tile .radio-label {\n  color: #2260ff;\n}\n\n.radio-input:focus + .radio-tile {\n  border-color: #2260ff;\n  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1), 0 0 0 4px #b5c9fc;\n}\n\n.radio-input:focus + .radio-tile:before {\n  transform: scale(1);\n  opacity: 1;\n}\n\n.radio-tile {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  width: 80px;\n  min-height: 80px;\n  border-radius: 0.5rem;\n  border: 2px solid #b5bfd9;\n  background-color: #fff;\n  box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);\n  transition: 0.15s ease;\n  cursor: pointer;\n  position: relative;\n}\n\n.radio-tile:before {\n  content: \"\";\n  position: absolute;\n  display: block;\n  width: 0.75rem;\n  height: 0.75rem;\n  border: 2px solid #b5bfd9;\n  background-color: #fff;\n  border-radius: 50%;\n  top: 0.25rem;\n  left: 0.25rem;\n  opacity: 0;\n  transform: scale(0);\n  transition: 0.25s ease;\n}\n\n.radio-tile:hover {\n  border-color: #2260ff;\n}\n\n.radio-tile:hover:before {\n  transform: scale(1);\n  opacity: 1;\n}\n\n.radio-icon svg {\n  width: 2rem;\n  height: 2rem;\n  fill: #494949;\n}\n\n.radio-label {\n  color: #707070;\n  transition: 0.375s ease;\n  text-align: center;\n  font-size: 13px;\n}\n\n.radio-input {\n  clip: rect(0 0 0 0);\n  -webkit-clip-path: inset(100%);\n  clip-path: inset(100%);\n  height: 1px;\n  overflow: hidden;\n  position: absolute;\n  white-space: nowrap;\n  width: 1px;\n}"
