    "html": "<div class=\"radio-input\">\n  <label class=\"label\">\n    <input value=\"value-1\" name=\"value-radio\" id=\"value-1\" type=\"radio\" />\n    <span class=\"text\">Play</span>\n  </label>\n  <label class=\"label\">\n    <input value=\"value-1\" name=\"value-radio\" id=\"value-1\" type=\"radio\" />\n    <span class=\"text\">Stop</span>\n  </label>\n  <label class=\"label\">\n    <input value=\"value-1\" name=\"value-radio\" id=\"value-1\" type=\"radio\" />\n    <span class=\"text\">Reset</span>\n  </label>\n</div>\n",
    "css": ".radio-input {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  background-color: black;\n  padding: 4px;\n  border-radius: 10px;\n  z-index: -1;\n}\n\n.radio-input input {\n  display: none;\n}\n\n.radio-input .label {\n  width: 90px;\n  height: 60px;\n  background: linear-gradient(to bottom, #333333, rgb(36, 35, 35));\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 8px;\n  transition: all 0.1s linear;\n  border-top: 1px solid #4e4d4d;\n  background-color: #333333;\n  position: relative;\n  cursor: pointer;\n  box-shadow: 0px 17px 5px 1px rgba(0, 0, 0, 0.2);\n}\n\n.label:has(input[type=\"radio\"]:checked) {\n  box-shadow: 0px 17px 5px 1px rgba(0, 0, 0, 0);\n  background: linear-gradient(to bottom, #1d1d1d, #1d1d1d);\n  border-top: none;\n}\n\n.label:first-child {\n  border-top-left-radius: 6px;\n  border-bottom-left-radius: 6px;\n}\n\n.label:last-child {\n  border-top-right-radius: 6px;\n  border-bottom-right-radius: 6px;\n}\n\n.label::before {\n  content: \"\";\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 103%;\n  height: 100%;\n  border-radius: 10px;\n  background: linear-gradient(\n    to bottom,\n    transparent 10%,\n    transparent,\n    transparent 90%\n  );\n  transition: all 0.1s linear;\n  z-index: -1;\n}\n\n.label:has(input[type=\"radio\"]:checked)::before {\n  background: linear-gradient(\n    to bottom,\n    transparent 10%,\n    #cae2fd63,\n    transparent 90%\n  );\n}\n\n.label .text {\n  color: black;\n  font-size: 15px;\n  line-height: 12px;\n  padding: 0px;\n  font-weight: 800;\n  text-transform: uppercase;\n  transition: all 0.1s linear;\n  text-shadow:\n    -1px -1px 1px rgb(224, 224, 224, 0.1),\n    0px 2px 3px rgb(0, 0, 0, 0.3);\n}\n\n.label input[type=\"radio\"]:checked + .text {\n  color: rgb(202, 226, 253);\n  text-shadow: 0px 0px 12px #cae2fd;\n}\n"
