    "css": ".input {\n  display: flex;\n  flex-direction: column;\n  width: 200px;\n  background-color: #0D1117;\n  justify-content: center;\n  border-radius: 5px\n}\n\n.value {\n  background-color: transparent;\n  border: none;\n  padding: 10px;\n  color: white;\n  display: flex;\n  position: relative;\n  gap: 5px;\n  cursor: pointer;\n  border-radius: 4px;\n}\n\n.value:not(:active):hover,\n.value:focus {\n  background-color: #21262C;\n}\n\n.value:focus,\n.value:active {\n  background-color: #1A1F24;\n  outline: none;\n}\n\n.value::before {\n  content: \"\";\n  position: absolute;\n  top: 5px;\n  left: -10px;\n  width: 5px;\n  height: 80%;\n  background-color: #2F81F7;\n  border-radius: 5px;\n  opacity: 0;\n}\n\n.value:focus::before,\n.value:active::before {\n  opacity: 1;\n}\n\n.value svg {\n  width: 15px\n}"
