    "html": "<div class=\"radio-input\">\n  <input value=\"value-1\" name=\"value-radio\" id=\"value-1\" type=\"radio\">\n  <div class=\"plus1\">\n    <div class=\"plus2\"></div>\n  </div>\n  <input value=\"value-2\" name=\"value-radio\" id=\"value-2\" type=\"radio\" checked=\"\">\n  <div class=\"plus1\">\n    <div class=\"plus2\"></div>\n  </div>\n  <input value=\"value-3\" name=\"value-radio\" id=\"value-3\" type=\"radio\">\n  <div class=\"plus1\">\n    <div class=\"plus2\"></div>\n  </div>\n</div>",
    "css": ".radio-input {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.radio-input input {\n  appearance: none;\n  width: 2em;\n  height: 2em;\n  background-color: #171717;\n  box-shadow: inset 2px 5px 10px rgb(5, 5, 5);\n  border-radius: 5px;\n  transition: .4s ease-in-out;\n}\n\n.radio-input input:hover {\n  scale: 1.2;\n  cursor: pointer;\n  box-shadow: none;\n}\n\n.radio-input .plus1 {\n  position: relative;\n  top: 0.01em;\n  left: -1.45em;\n  width: 1.3em;\n  height: 0.2em;\n  background-color: red;\n  rotate: 45deg;\n  scale: 0;\n  border-radius: 5px;\n  transition: .4s ease-in-out;\n}\n\n.radio-input .plus2 {\n  position: relative;\n  width: 1.3em;\n  height: 0.2em;\n  background-color: red;\n  transform: rotate(90deg);\n  border-radius: 5px;\n  transition: .4s ease-in-out;\n}\n\n.radio-input input:checked {\n  box-shadow: none;\n}\n\n.radio-input input:checked + .plus1 {\n  transform: rotate(180deg);\n  scale: 1;\n}"
