    "createdAt": "2026-09-11T00:00:00Z",
    "html": "<div class=\"flex flex-col space-y-4 p-5\">\n  <label class=\"relative flex items-center cursor-pointer\">\n    <input\n      checked=\"\"\n      class=\"sr-only peer\"\n      name=\"futuristic-radio\"\n      type=\"radio\"\n    />\n    <div\n      class=\"w-6 h-6 bg-transparent border-2 border-red-500 rounded-full peer-checked:bg-red-500 peer-checked:border-red-500 peer-hover:shadow-lg peer-hover:shadow-red-500/50 peer-checked:shadow-lg peer-checked:shadow-red-500/50 transition duration-300 ease-in-out\"\n    ></div>\n    <span class=\"ml-2 text-white\">Hard</span>\n  </label>\n  <label class=\"relative flex items-center cursor-pointer\">\n    <input class=\"sr-only peer\" name=\"futuristic-radio\" type=\"radio\" />\n    <div\n      class=\"w-6 h-6 bg-transparent border-2 border-yellow-500 rounded-full peer-checked:bg-yellow-500 peer-checked:border-yellow-500 peer-hover:shadow-lg peer-hover:shadow-yellow-500/50 peer-checked:shadow-lg peer-checked:shadow-yellow-500/50 transition duration-300 ease-in-out\"\n    ></div>\n    <span class=\"ml-2 text-white\">Normal</span>\n  </label>\n  <label class=\"relative flex items-center cursor-pointer\">\n    <input class=\"sr-only peer\" name=\"futuristic-radio\" type=\"radio\" />\n    <div\n      class=\"w-6 h-6 bg-transparent border-2 border-green-500 rounded-full peer-checked:bg-green-500 peer-checked:border-green-500 peer-hover:shadow-lg peer-hover:shadow-green-500/50 peer-checked:shadow-lg peer-checked:shadow-green-500/50 transition duration-300 ease-in-out\"\n    ></div>\n    <span class=\"ml-2 text-white\">Easy</span>\n  </label>\n</div>\n",
    "css": ".sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border-width: 0;\n}\n.relative {\n  position: relative;\n}\n.ml-2 {\n  margin-left: 0.5rem;\n}\n.flex {\n  display: flex;\n}\n.h-6 {\n  height: 1.5rem;\n}\n.w-6 {\n  width: 1.5rem;\n}\n.cursor-pointer {\n  cursor: pointer;\n}\n.flex-col {\n  flex-direction: column;\n}\n.items-center {\n  align-items: center;\n}\n.space-y-4 > :not([hidden]) ~ :not([hidden]) {\n  --tw-space-y-reverse: 0;\n  margin-top: calc(1rem * calc(1 - var(--tw-space-y-reverse)));\n  margin-bottom: calc(1rem * var(--tw-space-y-reverse));\n}\n.rounded-full {\n  border-radius: 9999px;\n}\n.border-2 {\n  border-width: 2px;\n}\n.border-green-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(34 197 94 / var(--tw-border-opacity));\n}\n.border-red-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(239 68 68 / var(--tw-border-opacity));\n}\n.border-yellow-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(234 179 8 / var(--tw-border-opacity));\n}\n.bg-transparent {\n  background-color: transparent;\n}\n.p-5 {\n  padding: 1.25rem;\n}\n.text-white {\n  --tw-text-opacity: 1;\n  color: rgb(255 255 255 / var(--tw-text-opacity));\n}\n.transition {\n  transition-property: color, background-color, border-color, fill, stroke,\n    opacity, box-shadow, transform, filter, -webkit-text-decoration-color,\n    -webkit-backdrop-filter;\n  transition-property: color, background-color, border-color,\n    text-decoration-color, fill, stroke, opacity, box-shadow, transform, filter,\n    backdrop-filter;\n  transition-property: color, background-color, border-color,\n    text-decoration-color, fill, stroke, opacity, box-shadow, transform, filter,\n    backdrop-filter, -webkit-text-decoration-color, -webkit-backdrop-filter;\n  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);\n  transition-duration: 150ms;\n}\n.duration-300 {\n  transition-duration: 300ms;\n}\n.ease-in-out {\n  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);\n}\n.peer:checked ~ .peer-checked\\:border-green-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(34 197 94 / var(--tw-border-opacity));\n}\n.peer:checked ~ .peer-checked\\:border-red-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(239 68 68 / var(--tw-border-opacity));\n}\n.peer:checked ~ .peer-checked\\:border-yellow-500 {\n  --tw-border-opacity: 1;\n  border-color: rgb(234 179 8 / var(--tw-border-opacity));\n}\n.peer:checked ~ .peer-checked\\:bg-green-500 {\n  --tw-bg-opacity: 1;\n  background-color: rgb(34 197 94 / var(--tw-bg-opacity));\n}\n.peer:checked ~ .peer-checked\\:bg-red-500 {\n  --tw-bg-opacity: 1;\n  background-color: rgb(239 68 68 / var(--tw-bg-opacity));\n}\n.peer:checked ~ .peer-checked\\:bg-yellow-500 {\n  --tw-bg-opacity: 1;\n  background-color: rgb(234 179 8 / var(--tw-bg-opacity));\n}\n.peer:checked ~ .peer-checked\\:shadow-lg {\n  --tw-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1),\n    0 4px 6px -4px rgb(0 0 0 / 0.1);\n  --tw-shadow-colored: 0 10px 15px -3px var(--tw-shadow-color),\n    0 4px 6px -4px var(--tw-shadow-color);\n  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),\n    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);\n}\n.peer:checked ~ .peer-checked\\:shadow-green-500\\/50 {\n  --tw-shadow-color: rgb(34 197 94 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n.peer:checked ~ .peer-checked\\:shadow-red-500\\/50 {\n  --tw-shadow-color: rgb(239 68 68 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n.peer:checked ~ .peer-checked\\:shadow-yellow-500\\/50 {\n  --tw-shadow-color: rgb(234 179 8 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n.peer:hover ~ .peer-hover\\:shadow-lg {\n  --tw-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1),\n    0 4px 6px -4px rgb(0 0 0 / 0.1);\n  --tw-shadow-colored: 0 10px 15px -3px var(--tw-shadow-color),\n    0 4px 6px -4px var(--tw-shadow-color);\n  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000),\n    var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow);\n}\n.peer:hover ~ .peer-hover\\:shadow-green-500\\/50 {\n  --tw-shadow-color: rgb(34 197 94 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n.peer:hover ~ .peer-hover\\:shadow-red-500\\/50 {\n  --tw-shadow-color: rgb(239 68 68 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n.peer:hover ~ .peer-hover\\:shadow-yellow-500\\/50 {\n  --tw-shadow-color: rgb(234 179 8 / 0.5);\n  --tw-shadow: var(--tw-shadow-colored);\n}\n"
