    "html": "<div class=\"rating\">\n  <input type=\"radio\" id=\"star-1\" name=\"star-radio\" value=\"star-1\">\n  <label for=\"star-1\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path pathLength=\"360\" d=\"M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z\"></path></svg>\n  </label>\n  <input type=\"radio\" id=\"star-2\" name=\"star-radio\" value=\"star-1\">\n  <label for=\"star-2\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path pathLength=\"360\" d=\"M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z\"></path></svg>\n  </label>\n  <input type=\"radio\" id=\"star-3\" name=\"star-radio\" value=\"star-1\">\n  <label for=\"star-3\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path pathLength=\"360\" d=\"M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z\"></path></svg>\n  </label>\n  <input type=\"radio\" id=\"star-4\" name=\"star-radio\" value=\"star-1\">\n  <label for=\"star-4\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path pathLength=\"360\" d=\"M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z\"></path></svg>\n  </label>\n  <input type=\"radio\" id=\"star-5\" name=\"star-radio\" value=\"star-1\">\n  <label for=\"star-5\">\n    <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\"><path pathLength=\"360\" d=\"M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z\"></path></svg>\n  </label>\n</div>",
    "css": ".rating {\n  display: flex;\n  flex-direction: row-reverse;\n  gap: 0.3rem;\n  --stroke: #666;\n  --fill: #ffc73a;\n}\n\n.rating input {\n  appearance: unset;\n}\n\n.rating label {\n  cursor: pointer;\n}\n\n.rating svg {\n  width: 2rem;\n  height: 2rem;\n  overflow: visible;\n  fill: transparent;\n  stroke: var(--stroke);\n  stroke-linejoin: bevel;\n  stroke-dasharray: 12;\n  animation: idle 4s linear infinite;\n  transition: stroke 0.2s, fill 0.5s;\n}\n\n@keyframes idle {\n  from {\n    stroke-dashoffset: 24;\n  }\n}\n\n.rating label:hover svg {\n  stroke: var(--fill);\n}\n\n.rating input:checked ~ label svg {\n  transition: 0s;\n  animation: idle 4s linear infinite, yippee 0.75s backwards;\n  fill: var(--fill);\n  stroke: var(--fill);\n  stroke-opacity: 0;\n  stroke-dasharray: 0;\n  stroke-linejoin: miter;\n  stroke-width: 8px;\n}\n\n@keyframes yippee {\n  0% {\n    transform: scale(1);\n    fill: var(--fill);\n    fill-opacity: 0;\n    stroke-opacity: 1;\n    stroke: var(--stroke);\n    stroke-dasharray: 10;\n    stroke-width: 1px;\n    stroke-linejoin: bevel;\n  }\n\n  30% {\n    transform: scale(0);\n    fill: var(--fill);\n    fill-opacity: 0;\n    stroke-opacity: 1;\n    stroke: var(--stroke);\n    stroke-dasharray: 10;\n    stroke-width: 1px;\n    stroke-linejoin: bevel;\n  }\n\n  30.1% {\n    stroke: var(--fill);\n    stroke-dasharray: 0;\n    stroke-linejoin: miter;\n    stroke-width: 8px;\n  }\n\n  60% {\n    transform: scale(1.2);\n    fill: var(--fill);\n  }\n}\n"
