    "css": ".main-container {\n  background-color: #08505a;\n  padding: 4px;\n  border-radius: 16px 16px 2px 2px;\n}\n\n.radio-input,\n.url-bar {\n  color: #ceecf0;\n  background-color: #2b7781;\n  padding: 4px 0 0 4px;\n  border-radius: 12px 12px 0 0;\n  display: flex;\n}\n\n.url-bar {\n  border-radius: 0 0 8px 8px;\n}\n\n.controls {\n  display: flex;\n  padding: 0 8px;\n  margin-left: 36px;\n  gap: 8px;\n  height: 32px;\n  align-items: center;\n  justify-content: center;\n}\n\n.option {\n  padding: 0 4px;\n  display: flex;\n  align-items: center;\n  border-radius: 10px 10px 0 0;\n  background-color: #2b7781;\n}\n\n.new-tab {\n  padding: 0 8px;\n  border-left: 1px solid #08505a;\n  border-radius: 0;\n  height: 16px;\n  margin-top: 8px;\n}\n\n.label {\n  cursor: pointer;\n  margin-right: 24px;\n}\n\n.input[type=\"radio\"] {\n  appearance: none;\n  display: flex;\n  margin: 0;\n}\n\n.favicon {\n  margin-right: 8px;\n  margin-top: 4px;\n}\n\n.option:has(.input:checked) {\n  position: relative;\n  background-color: #08505a;\n  transition: all 200ms;\n  .url {\n    transition: all 200ms;\n    display: block;\n  }\n}\n\n.option:has(.lovable:checked) {\n  .url {\n    left: -96px;\n  }\n}\n\n.url {\n  display: none;\n  position: absolute;\n  bottom: -36px;\n  left: 14px;\n}\n\n.url-bar-container {\n  padding: 8px;\n  background-color: #08505a;\n}\n\n.url-bar {\n  background-color: #2b7781;\n  border-radius: 16px;\n  height: 32px;\n}\n\n.content-container {\n  height: 100px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.content {\n  font-size: 14px;\n  height: 64px;\n  width: 228px;\n  color: #ceecf0;\n  background-color: #2b7781;\n  padding: 2px 8px 2px 4px;\n  border-radius: 8px;\n  position: relative;\n}\n\n.cursor {\n  animation: 1s flash infinite;\n}\n\n.send-btn {\n  position: absolute;\n  bottom: 4px;\n  right: 4px;\n  cursor: pointer;\n}\n\n.attach-btn {\n  position: absolute;\n  bottom: 4px;\n  left: 4px;\n  cursor: pointer;\n}\n\n.private-btn {\n  position: absolute;\n  bottom: 4px;\n  right: 24px;\n  cursor: pointer;\n}\n\n@keyframes flash {\n  0% {\n    opacity: 0;\n  }\n  25% {\n    opacity: 0;\n  }\n  26% {\n    opacity: 1;\n  }\n  96% {\n    opacity: 1;\n  }\n}\n"
