    "html": "\n  <div class=\"radio-group\">\n    <input class=\"radio-input\" name=\"radio-group\" id=\"radio1\" type=\"radio\">\n    <label class=\"radio-label\" for=\"radio1\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 1\n    </label>\n    \n    <input class=\"radio-input\" name=\"radio-group\" id=\"radio2\" type=\"radio\">\n    <label class=\"radio-label\" for=\"radio2\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 2\n    </label>\n    \n    <input class=\"radio-input\" name=\"radio-group\" id=\"radio3\" type=\"radio\">\n    <label class=\"radio-label\" for=\"radio3\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 3\n    </label>\n  </div>\n\n\n",
    "css": "* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: Arial, sans-serif;\n  background-color: #f1f1f1;\n  padding: 20px;\n}\n\n.radio-group {\n  display: flex;\n  flex-direction: column;\n}\n\n.radio-label {\n  display: flex;\n  align-items: center;\n  padding: 0.5em;\n  margin-bottom: 0.5em;\n  background-color: #fff;\n  border: 1px solid #ccc;\n  border-radius: 4px;\n  transition: background-color 0.2s, border-color 0.2s;\n}\n\n.radio-label:hover {\n  background-color: #e6e6e6;\n}\n\n.radio-input {\n  position: absolute;\n  opacity: 0;\n}\n\n.radio-input:checked + .radio-label {\n  background-color: #ffc3c3;\n  border-color: #ff1111;\n}\n\n.radio-input:focus + .radio-label {\n  outline: 2px solid #ff1111;\n}\n\n.radio-inner-circle {\n  display: inline-block;\n  width: 1em;\n  height: 1em;\n  border: 2px solid #888;\n  border-radius: 50%;\n  margin-right: 0.5em;\n  transition: border-color 0.2s;\n  position: relative;\n}\n\n.radio-label:hover .radio-inner-circle {\n  border-color: #555;\n}\n\n.radio-input:checked + .radio-label .radio-inner-circle {\n  border-color: #ff1111;\n}\n\n.radio-input:checked + .radio-label .radio-inner-circle::after {\n  content: '';\n  display: block;\n  width: 0.5em;\n  height: 0.5em;\n  background-color: #ff1111;\n  border-radius: 50%;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}\n    "
