    "html": "\n  <div class=\"radio-group\">\n    <input type=\"radio\" id=\"radio1\" name=\"radio-group\" class=\"radio-input\">\n    <label for=\"radio1\" class=\"radio-label\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 1\n    </label>\n    \n    <input type=\"radio\" id=\"radio2\" name=\"radio-group\" class=\"radio-input\">\n    <label for=\"radio2\" class=\"radio-label\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 2\n    </label>\n    \n    <input type=\"radio\" id=\"radio3\" name=\"radio-group\" class=\"radio-input\">\n    <label for=\"radio3\" class=\"radio-label\">\n      <span class=\"radio-inner-circle\"></span>\n      Option 3\n    </label>\n  </div>\n\n\n",
    "css": ".radio-group {\n  display: flex;\n  flex-direction: column;\n}\n\n.radio-label {\n  display: flex;\n  align-items: center;\n  padding: 0.5em;\n  margin-bottom: 0.5em;\n  background-color: rgb(17, 17, 17);\n  border: 1px solid #ccc;\n  border-radius: 4px;\n  transition: background-color 0.2s, border-color 0.2s;\n  color: #fff;\n}\n\n.radio-label:hover {\n  background-color: #000000;\n}\n\n.radio-input {\n  position: absolute;\n  opacity: 0;\n}\n\n.radio-input:checked + .radio-label {\n  background-color: #b80000;\n  border-color: #ff1111;\n}\n\n.radio-input:focus + .radio-label {\n  outline: 2px solid #ff1111;\n}\n\n.radio-inner-circle {\n  display: inline-block;\n  width: 1em;\n  height: 1em;\n  border: 2px solid rgb(255, 255, 255);\n  border-radius: 50%;\n  margin-right: 0.5em;\n  transition: border-color 0.2s;\n  position: relative;\n}\n\n.radio-label:hover .radio-inner-circle {\n  border-color: rgb(233, 233, 233);\n}\n\n.radio-input:checked + .radio-label .radio-inner-circle {\n  border-color: #ff1111;\n}\n\n.radio-input:checked + .radio-label .radio-inner-circle::after {\n  content: '';\n  display: block;\n  width: 0.5em;\n  height: 0.5em;\n  background-color: #ff1111;\n  border-radius: 50%;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}\n    "
