    "createdAt": "2026-09-11T00:00:00Z",
    "html": "<div class=\"container\">\n  <div class=\"radio-wrapper\">\n    <input type=\"radio\" id=\"value-1\" name=\"btn\" class=\"input\" />\n    <div class=\"btn\">\n      <span aria-hidden=\"\">_</span>Cyber\n      <span aria-hidden=\"\" class=\"btn__glitch\">_Cyber🦾</span>\n      <label class=\"number\">r1</label>\n    </div>\n  </div>\n  <div class=\"radio-wrapper\">\n    <input type=\"radio\" checked=\"true\" id=\"value-2\" name=\"btn\" class=\"input\" />\n    <div class=\"btn\">\n      _Radio<span aria-hidden=\"\">_</span>\n      <span aria-hidden=\"\" class=\"btn__glitch\">_R_a_d_i_o_</span>\n      <label class=\"number\">r2</label>\n    </div>\n  </div>\n  <div class=\"radio-wrapper\">\n    <input type=\"radio\" id=\"value-3\" name=\"btn\" class=\"input\" />\n    <div class=\"btn\">\n      Buttons<span aria-hidden=\"\"></span>\n      <span aria-hidden=\"\" class=\"btn__glitch\">Buttons_</span>\n      <label class=\"number\">r3</label>\n    </div>\n  </div>\n</div>\n",
    "css": ".container {\n  display: flex;\n  flex-direction: row;\n}\n\n.radio-wrapper {\n  position: relative;\n  height: 38px;\n  width: 84px;\n  margin: 3px;\n}\n\n.radio-wrapper .input {\n  position: absolute;\n  height: 100%;\n  width: 100%;\n  margin: 0;\n  cursor: pointer;\n  z-index: 10;\n  opacity: 0;\n}\n\n.btn {\n  --primary: #f5434f;\n  --shadow-primary: #631e29;\n  --color: #ffffff;\n  --font-size: 9px;\n  --shadow-primary-hue: 180;\n  --shadow-secondary-hue: 60;\n  --shadow-secondary: #000000;\n  --clip: polygon(\n    11% 0,\n    95% 0,\n    100% 25%,\n    90% 90%,\n    95% 90%,\n    85% 90%,\n    85% 100%,\n    7% 100%,\n    0 80%\n  );\n  --border: 5px;\n  --shimmy-distance: 5;\n  --clip-one: polygon(\n    0 2%,\n    100% 2%,\n    100% 95%,\n    95% 95%,\n    95% 90%,\n    85% 90%,\n    85% 95%,\n    8% 95%,\n    0 70%\n  );\n  --clip-two: polygon(\n    0 78%,\n    100% 78%,\n    100% 100%,\n    95% 100%,\n    95% 90%,\n    85% 90%,\n    85% 100%,\n    8% 100%,\n    0 78%\n  );\n  --clip-three: polygon(\n    0 44%,\n    100% 44%,\n    100% 54%,\n    95% 54%,\n    95% 54%,\n    85% 54%,\n    85% 54%,\n    8% 54%,\n    0 54%\n  );\n  --clip-four: polygon(\n    0 0,\n    100% 0,\n    100% 0,\n    95% 0,\n    95% 0,\n    85% 0,\n    85% 0,\n    8% 0,\n    0 0\n  );\n  --clip-five: polygon(\n    0 0,\n    100% 0,\n    100% 0,\n    95% 0,\n    95% 0,\n    85% 0,\n    85% 0,\n    8% 0,\n    0 0\n  );\n  --clip-six: polygon(\n    0 40%,\n    100% 40%,\n    100% 85%,\n    95% 85%,\n    95% 85%,\n    85% 85%,\n    85% 85%,\n    8% 85%,\n    0 70%\n  );\n  --clip-seven: polygon(\n    0 63%,\n    100% 63%,\n    100% 80%,\n    95% 80%,\n    95% 80%,\n    85% 80%,\n    85% 80%,\n    8% 80%,\n    0 70%\n  );\n  color: var(--color);\n  text-transform: uppercase;\n  font-size: var(--font-size);\n  letter-spacing: 3px;\n  position: relative;\n  font-weight: 900;\n  width: 100%;\n  height: 100%;\n  line-height: 38px;\n  text-align: center;\n  transition: background 0.2s, 0.3s;\n  font-family: \"Orbitron\", sans-serif; /* Orbitron font */\n}\n\n.input:checked + .btn {\n  --primary: #161a25;\n  --shadow-primary: #ffffff;\n}\n\n.input:hover + .btn {\n  --primary: #cc133c;\n  --font-size: 11px;\n}\n\n.btn:after,\n.btn:before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  clip-path: var(--clip);\n  z-index: -1;\n}\n\n.btn:before {\n  background: var(--shadow-primary);\n  transform: translate(var(--border), 0);\n}\n\n.btn:after {\n  background: var(--primary);\n}\n\n.btn__tag {\n  position: absolute;\n  padding: 1px 4px;\n  letter-spacing: 1px;\n  line-height: 1;\n  bottom: -5%;\n  right: 5%;\n  font-weight: normal;\n  color: hsl(0, 0%, 0%);\n  font-size: var(--label-size);\n}\n\n.btn__glitch {\n  position: absolute;\n  top: calc(var(--border) * -1);\n  left: calc(var(--border) * -1);\n  right: calc(var(--border) * -1);\n  bottom: calc(var(--border) * -1);\n  background: var(--shadow-primary);\n  text-shadow: 2px 2px var(--shadow-primary), -2px -2px var(--shadow-secondary);\n  clip-path: var(--clip);\n  animation: glitch 2s infinite;\n  display: none;\n}\n\n.input:hover + .btn .btn__glitch {\n  display: block;\n}\n\n.input:checked + .btn .btn__glitch {\n  display: block;\n  animation: glitch 5s infinite;\n}\n\n.btn__glitch:before {\n  content: \"\";\n  position: absolute;\n  top: calc(var(--border) * 1);\n  right: calc(var(--border) * 1);\n  bottom: calc(var(--border) * 1);\n  left: calc(var(--border) * 1);\n  clip-path: var(--clip);\n  background: var(--primary);\n  z-index: -1;\n}\n\n@keyframes glitch {\n  0% {\n    clip-path: var(--clip-one);\n  }\n\n  2%,\n  8% {\n    clip-path: var(--clip-two);\n    transform: translate(calc(var(--shimmy-distance) * -1%), 0);\n  }\n\n  6% {\n    clip-path: var(--clip-two);\n    transform: translate(calc(var(--shimmy-distance) * 1%), 0);\n  }\n\n  9% {\n    clip-path: var(--clip-two);\n    transform: translate(0, 0);\n  }\n\n  10% {\n    clip-path: var(--clip-three);\n    transform: translate(calc(var(--shimmy-distance) * 1%), 0);\n  }\n\n  13% {\n    clip-path: var(--clip-three);\n    transform: translate(0, 0);\n  }\n\n  14%,\n  21% {\n    clip-path: var(--clip-four);\n    transform: translate(calc(var(--shimmy-distance) * 1%), 0);\n  }\n\n  25% {\n    clip-path: var(--clip-five);\n    transform: translate(calc(var(--shimmy-distance) * 1%), 0);\n  }\n\n  30% {\n    clip-path: var(--clip-five);\n    transform: translate(calc(var(--shimmy-distance) * -1%), 0);\n  }\n\n  35%,\n  45% {\n    clip-path: var(--clip-six);\n    transform: translate(calc(var(--shimmy-distance) * -1%));\n  }\n\n  40% {\n    clip-path: var(--clip-six);\n    transform: translate(calc(var(--shimmy-distance) * 1%));\n  }\n\n  50% {\n    clip-path: var(--clip-six);\n    transform: translate(0, 0);\n  }\n\n  55% {\n    clip-path: var(--clip-seven);\n    transform: translate(calc(var(--shimmy-distance) * 1%), 0);\n  }\n\n  60% {\n    clip-path: var(--clip-seven);\n    transform: translate(0, 0);\n  }\n\n  31%,\n  61%,\n  100% {\n    clip-path: var(--clip-four);\n  }\n}\n\n.number {\n  background: var(--shadow-primary);\n  color: #323232;\n  font-size: 5.5px;\n  font-weight: 700;\n  letter-spacing: 1px;\n  position: absolute;\n  width: 15px;\n  height: 6px;\n  top: 0;\n  left: 81%;\n  line-height: 6.2px;\n}\n"
