    "html": "<input hidden=\"\" class=\"mode\" id=\"theme-mode\" type=\"checkbox\" />\n<div class=\"container\">\n  <div class=\"wrap\">\n    <input\n      hidden=\"\"\n      class=\"rd-1\"\n      name=\"radio\"\n      id=\"rd-1\"\n      type=\"radio\"\n      checked=\"\"\n    />\n    <label style=\"--index: 0;\" class=\"label\" for=\"rd-1\"\n      ><span>About Me</span></label\n    >\n\n    <input hidden=\"\" class=\"rd-2\" name=\"radio\" id=\"rd-2\" type=\"radio\" />\n    <label style=\"--index: 1;\" class=\"label\" for=\"rd-2\"\n      ><span>Summary</span></label\n    >\n\n    <input hidden=\"\" class=\"rd-3\" name=\"radio\" id=\"rd-3\" type=\"radio\" />\n    <label style=\"--index: 2;\" class=\"label\" for=\"rd-3\"\n      ><span>Portfolio</span></label\n    >\n\n    <div class=\"bar\"></div>\n    <div class=\"slidebar\"></div>\n\n    <label for=\"theme-mode\" class=\"theme\">\n      <span class=\"light\"\n        ><svg\n          xmlns=\"http://www.w3.org/2000/svg\"\n          viewBox=\"0 0 24 24\"\n          stroke-width=\"2\"\n        >\n          <path\n            d=\"M14.828 14.828a4 4 0 1 0 -5.656 -5.656a4 4 0 0 0 5.656 5.656z\"\n          ></path>\n          <g data-g=\"high\">\n            <path d=\"M4 12h-3\"></path>\n            <path d=\"M12 4v-3\"></path>\n            <path d=\"M20 12h3\"></path>\n            <path d=\"M12 20v3\"></path>\n          </g>\n          <g data-g=\"low\">\n            <path d=\"M6.343 17.657l-1.414 1.414\"></path>\n            <path d=\"M6.343 6.343l-1.414 -1.414\"></path>\n            <path d=\"M17.657 6.343l1.414 -1.414\"></path>\n            <path d=\"M17.657 17.657l1.414 1.414\"></path>\n          </g></svg\n      ></span>\n      <span class=\"dark\"\n        ><svg\n          xmlns=\"http://www.w3.org/2000/svg\"\n          viewBox=\"0 0 24 24\"\n          stroke-width=\"0\"\n        >\n          <path\n            d=\"m4.8.69c0-.38-.31-.69-.69-.69s-.69.31-.69.69v1.03h-1.03c-.38,0-.69.31-.69.69s.31.69.69.69h1.03v1.03c0,.38.31.69.69.69s.69-.31.69-.69v-1.03h1.03c.38,0,.69-.31.69-.69s-.31-.69-.69-.69h-1.03V.69Zm5.14,5.14c0-.38-.31-.69-.69-.69s-.69.31-.69.69v1.03h-1.03c-.38,0-.69.31-.69.69s.31.69.69.69h1.03v1.03c0,.38.31.69.69.69s.69-.31.69-.69v-1.03h1.03c.38,0,.69-.31.69-.69s-.31-.69-.69-.69h-1.03v-1.03Zm-6.86,5.14c0-.38-.31-.69-.69-.69s-.69.31-.69.69v1.03H.69c-.38,0-.69.31-.69.69s.31.69.69.69h1.03v1.03c0,.38.31.69.69.69s.69-.31.69-.69v-1.03h1.03c.38,0,.69-.31.69-.69s-.31-.69-.69-.69h-1.03v-1.03ZM14.47,1.51l-.51-.07c-.37-.04-.58.38-.37.69.24.35.46.71.67,1.08.86,1.59,1.35,3.42,1.35,5.36,0,5.61-4.08,10.26-9.43,11.16-.41.07-.84.12-1.27.14-.37.02-.57.45-.31.71.12.12.24.24.36.35l.12.11.45.39.32.25.21.15.32.22.3.2c.21.13.42.25.64.37l.45.23.45.2.52.21.42.15c.23.08.46.14.7.21.18.05.36.09.54.13.22.04.43.08.65.12l.54.07.46.04c.22.01.44.02.66.02,6.25,0,11.31-5.07,11.31-11.31,0-.43-.02-.85-.07-1.27l-.06-.48c-.06-.38-.14-.76-.23-1.13-.12-.44-.26-.88-.43-1.3l-.19-.46-.13-.28-.13-.26c-.27-.53-.58-1.03-.93-1.51l-.26-.34-.34-.41-.28-.31-.2-.21-.28-.27-.38-.34-.55-.45-.42-.3-.5-.33-.55-.32-.56-.28-.19-.09-.41-.17-.47-.18-.43-.14-.56-.15-.45-.1-.5-.09Zm3.19,7.4c0-1.76-.35-3.43-.98-4.96,3.31,1.52,5.61,4.86,5.61,8.73,0,5.3-4.3,9.6-9.6,9.6-1.49,0-2.89-.34-4.15-.94,2.5-.79,4.67-2.3,6.27-4.3.23.32.61.53,1.04.53.71,0,1.29-.58,1.29-1.29,0-.61-.43-1.12-1-1.25.11-.2.21-.4.3-.61.33.2.71.32,1.13.32,1.18,0,2.14-.96,2.14-2.14s-.96-2.14-2.14-2.14c.06-.51.09-1.02.09-1.54Z\"\n            fill=\"currentColor\"\n            clip-rule=\"evenodd\"\n            fill-rule=\"evenodd\"\n          ></path></svg\n      ></span>\n    </label>\n  </div>\n</div>\n",
    "css": "/* theme-mode-style */\n.mode + .container {\n  --color-pure: #000;\n  --color-primary: #e8e8e8;\n  --color-secondary: #212121;\n  --muted: #b8b8b8;\n}\n.mode:checked + .container {\n  --color-pure: #fff;\n  --color-primary: #212121;\n  --color-secondary: #fff;\n  --muted: #383838;\n}\n.container {\n  background-color: var(--color-secondary);\n  position: absolute;\n  width: 100%;\n  height: 110%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-direction: column;\n}\n.container .theme {\n  color: var(--color-secondary);\n  background-color: var(--color-primary);\n  position: relative;\n  cursor: pointer;\n  z-index: 9;\n  -webkit-user-select: none;\n  user-select: none;\n  border: 1px solid var(--muted);\n  border-radius: calc(var(--round) - var(--p-y));\n  margin-left: calc(var(--p-x) * 2);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 5px;\n  transition: background-color 0.25s linear;\n}\n.container .theme:hover {\n  background-color: var(--muted);\n}\n.container .theme::before {\n  content: \"\";\n  position: absolute;\n  left: calc(var(--p-x) * -1);\n  width: 1px;\n  height: 100%;\n  background-color: var(--muted);\n}\n.container .theme span {\n  border: none;\n  outline: none;\n  background-color: transparent;\n  padding: 0.125rem;\n  border-radius: 9999px;\n  align-items: center;\n  justify-content: center;\n}\n.mode:checked + .container .theme span.light,\n.mode + .container .theme span.dark {\n  display: none;\n}\n.mode + .container .theme span.light,\n.mode:checked + .container .theme span.dark {\n  display: flex;\n}\n.container .theme svg {\n  stroke-linejoin: round;\n  stroke-linecap: round;\n  stroke: currentColor;\n  fill: none;\n  height: 22px;\n  width: 22px;\n}\n\n/* main style */\n.wrap {\n  --round: 10px;\n  --p-x: 8px;\n  --p-y: 4px;\n  --w-label: 100px;\n  display: flex;\n  align-items: center;\n  padding: var(--p-y) var(--p-x);\n  position: relative;\n  background: var(--color-primary);\n  border-radius: var(--round);\n  max-width: 100%;\n  overflow-x: auto;\n  scrollbar-width: none;\n  -webkit-overflow-scrolling: touch;\n  top: 0;\n  z-index: 1;\n}\n\n.wrap input {\n  height: 0;\n  width: 0;\n  position: absolute;\n  overflow: hidden;\n  display: none;\n  visibility: hidden;\n}\n\n.label {\n  cursor: pointer;\n  outline: none;\n  font-size: 0.875rem;\n  letter-spacing: initial;\n  font-weight: 500;\n  color: var(--color-secondary);\n  background: transparent;\n  padding: 12px 16px;\n  width: var(--w-label);\n  min-width: var(--w-label);\n  text-decoration: none;\n  -webkit-user-select: none;\n  user-select: none;\n  transition: color 0.25s ease;\n  outline-offset: -6px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  z-index: 2;\n  -webkit-tap-highlight-color: transparent;\n}\n.label span {\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-box-orient: vertical;\n  -webkit-line-clamp: 1;\n}\n\n.wrap input[class*=\"rd-\"]:checked + label {\n  color: var(--color-pure);\n}\n\n.bar {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  position: absolute;\n  transform-origin: 0 0 0;\n  height: 100%;\n  width: var(--w-label);\n  z-index: 0;\n  transition: transform 0.5s cubic-bezier(0.33, 0.83, 0.99, 0.98);\n}\n.bar::before,\n.bar::after {\n  content: \"\";\n  position: absolute;\n  height: 4px;\n  width: 100%;\n  background: var(--color-secondary);\n}\n.bar::before {\n  top: 0;\n  border-radius: 0 0 9999px 9999px;\n}\n.bar::after {\n  bottom: 0;\n  border-radius: 9999px 9999px 0 0;\n}\n\n.slidebar {\n  position: absolute;\n  height: calc(100% - (var(--p-y) * 4));\n  width: var(--w-label);\n  border-radius: calc(var(--round) - var(--p-y));\n  background: var(--muted);\n  transform-origin: 0 0 0;\n  z-index: 0;\n  transition: transform 0.5s cubic-bezier(0.33, 0.83, 0.99, 0.98);\n}\n\n.rd-1:checked ~ .bar,\n.rd-1:checked ~ .slidebar,\n.rd-1 + label:hover ~ .slidebar {\n  transform: translateX(0) scaleX(1);\n}\n.rd-2:checked ~ .bar,\n.rd-2:checked ~ .slidebar,\n.rd-2 + label:hover ~ .slidebar {\n  transform: translateX(100%) scaleX(1);\n}\n.rd-3:checked ~ .bar,\n.rd-3:checked ~ .slidebar,\n.rd-3 + label:hover ~ .slidebar {\n  transform: translateX(200%) scaleX(1);\n}\n"
