    "html": "<div class=\"radio-input\">\n  <input\n    class=\"star s1\"\n    type=\"radio\"\n    id=\"value-1\"\n    name=\"value-radio\"\n    value=\"value-1\"\n  />\n  <input\n    class=\"star s2\"\n    type=\"radio\"\n    id=\"value-2\"\n    name=\"value-radio\"\n    value=\"value-2\"\n  />\n  <input\n    class=\"star s3\"\n    type=\"radio\"\n    id=\"value-3\"\n    name=\"value-radio\"\n    value=\"value-3\"\n  />\n  <input\n    class=\"star s4\"\n    type=\"radio\"\n    id=\"value-4\"\n    name=\"value-radio\"\n    value=\"value-4\"\n  />\n  <input\n    class=\"star s5\"\n    type=\"radio\"\n    id=\"value-5\"\n    name=\"value-radio\"\n    value=\"value-5\"\n  />\n</div>\n",
    "css": ".radio-input {\n  display: flex;\n  scale: 0.15;\n  transform: rotate(180deg);\n}\n\n.star {\n  margin: 1em;\n  appearance: none;\n  --color: white;\n  border-left: 6.4721359549996em solid transparent;\n  border-right: 6.4721359549996em solid transparent;\n  border-bottom: 4em solid var(--color);\n  transform: rotate(0deg);\n  cursor: pointer;\n}\n\n.star:before {\n  content: \"\";\n  border-left: 6.4721359549996em solid transparent;\n  border-right: 6.4721359549996em solid transparent;\n  border-top: 4em solid var(--color);\n  position: absolute;\n  left: -6.4721359549996em;\n  transform: rotate(108deg);\n}\n\n.star:after {\n  content: \"\";\n  border-left: 6.4721359549996em solid transparent;\n  border-right: 6.4721359549996em solid transparent;\n  border-top: 4em solid var(--color);\n  position: absolute;\n  left: -6.4721359549996em;\n  transform: rotate(253deg);\n}\n\n.radio-input > .star:hover ~ .star,\n.radio-input > .star:hover,\n.radio-input > .star:checked ~ .star,\n.radio-input > .star:checked {\n  --color: yellow;\n}\n\n.radio-input > .star:checked ~ .star,\n.radio-input > .star:checked {\n  animation: grow 0.5s linear forwards;\n  transition: transform 0.3s;\n}\n\n@keyframes grow {\n  50% {\n    scale: 2;\n  }\n}\n"
